const assert = require('assert');
const { readConfig } = require('./utils.js');

async function main() {
  const result = readConfig(5);
  assert(result && typeof result.then === 'function', 'readConfig(id) must return a Promise (result.then must be a function)');

  const cfg = await readConfig(5);
  assert.deepStrictEqual(cfg, { id: 5, name: 'config-5' }, `unexpected resolved value: ${JSON.stringify(cfg)}`);

  const cfg0 = await readConfig(0);
  assert.deepStrictEqual(cfg0, { id: 0, name: 'config-0' });

  let threw = false;
  try {
    await readConfig(-1);
  } catch (e) {
    threw = true;
    assert.strictEqual(e.message, 'invalid id', `expected error message 'invalid id', got '${e.message}'`);
  }
  assert(threw, 'expected readConfig(-1) to reject with an Error');

  console.log('PASS');
}

main().catch((e) => { console.error(e); process.exit(1); });

reference_solution.utils.js:
function readConfig(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id < 0) {
        reject(new Error('invalid id'));
        return;
      }
      resolve({ id, name: `config-${id}` });
    }, 10);
  });
}

module.exports = { readConfig };
